"s5-boundary": {
"svg": "<svg viewBox=\"0 0 440 228\" class=\"fig\" role=\"img\" aria-label=\"The decision boundary is where θᵀx = 0. With raw features it's a straight line (left); adding squared features lets the same model draw a circle (right).\"><defs><marker id=\"ah-s5b\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" class=\"ah\"/></marker><clipPath id=\"cp-s5b\"><rect x=\"0\" y=\"0\" width=\"440\" height=\"228\"/></clipPath></defs><path d=\"M30,62 L157.5,182 L200,182 L200,22 L30,22 Z\" class=\"zone1\"/><line x1=\"30\" y1=\"182\" x2=\"200\" y2=\"182\" class=\"ax\"/><line x1=\"30\" y1=\"22\" x2=\"30\" y2=\"182\" class=\"ax\"/><text x=\"30\" y=\"196\" class=\"ts\" text-anchor=\"middle\">0</text><text x=\"72.5\" y=\"196\" class=\"ts\" text-anchor=\"middle\">1</text><text x=\"115\" y=\"196\" class=\"ts\" text-anchor=\"middle\">2</text><text x=\"157.5\" y=\"196\" class=\"ts\" text-anchor=\"middle\">3</text><text x=\"200\" y=\"196\" class=\"ts\" text-anchor=\"middle\">4</text><text x=\"25\" y=\"186\" class=\"ts\" text-anchor=\"end\">0</text><text x=\"25\" y=\"146\" class=\"ts\" text-anchor=\"end\">1</text><text x=\"25\" y=\"106\" class=\"ts\" text-anchor=\"end\">2</text><text x=\"25\" y=\"66\" class=\"ts\" text-anchor=\"end\">3</text><text x=\"25\" y=\"26\" class=\"ts\" text-anchor=\"end\">4</text><line x1=\"30\" y1=\"62\" x2=\"157.5\" y2=\"182\" class=\"l2\"/><text x=\"149\" y=\"50\" class=\"tb\" text-anchor=\"middle\">y = 1</text><text x=\"64\" y=\"150\" class=\"tb\" text-anchor=\"middle\">y = 0</text><text x=\"115\" y=\"14\" class=\"ts\" text-anchor=\"middle\">θ = (−3, 1, 1): x₁ + x₂ = 3</text><rect x=\"250\" y=\"22\" width=\"170\" height=\"160\" rx=\"0\" class=\"under\"/><rect x=\"250\" y=\"22\" width=\"170\" height=\"160\" rx=\"0\" class=\"zone1\"/><ellipse cx=\"335\" cy=\"102\" rx=\"42.5\" ry=\"40\" class=\"zone0\"/><ellipse cx=\"335\" cy=\"102\" rx=\"42.5\" ry=\"40\" class=\"l2f\"/><text x=\"335\" y=\"106\" class=\"tb\" text-anchor=\"middle\">y = 0</text><text x=\"396.6\" y=\"38\" class=\"tb\" text-anchor=\"middle\">y = 1</text><text x=\"335\" y=\"14\" class=\"ts\" text-anchor=\"middle\">with x₁², x₂²: x₁² + x₂² = 1</text><text x=\"115\" y=\"222\" class=\"ts2\" text-anchor=\"middle\">straight boundary</text><text x=\"335\" y=\"222\" class=\"ts2\" text-anchor=\"middle\">curved boundary (unit circle)</text></svg>",
"caption": "The decision boundary is where θᵀx = 0. With raw features it's a straight line (left); adding squared features lets the same model draw a circle (right)."
},
