"d1\"><title>8</title></circle><circle cx=\"183.1\" cy=\"52\" r=\"5\" class=\"d1\"><title>5</title></circle><circle cx=\"141.9\" cy=\"52\" r=\"5\" class=\"d1\"><title>3</title></circle><circle cx=\"224.4\" cy=\"52\" r=\"5\" class=\"d1\"><title>7</title></circle><circle cx=\"245\" cy=\"41\" r=\"5\" class=\"d1\"><title>8</title></circle><circle cx=\"183.1\" cy=\"41\" r=\"5\" class=\"d1\"><title>5</title></circle><circle cx=\"121.2\" cy=\"41\" r=\"5\" class=\"d1\"><title>2</title></circle><circle cx=\"183.1\" cy=\"30\" r=\"5\" class=\"d1\"><title>5</title></circle><text x=\"72\" y=\"56\" class=\"tb\" text-anchor=\"end\">Group 1</text><circle cx=\"100.6\" cy=\"112\" r=\"5\" class=\"d2\"><title>1</title></circle><circle cx=\"389.4\" cy=\"112\" r=\"5\" class=\"d2\"><title>15</title></circle><circle cx=\"183.1\" cy=\"112\" r=\"5\" class=\"d2\"><title>5</title></circle><circle cx=\"183.1\" cy=\"101\" r=\"5\" class=\"d2\"><title>5</title></circle><circle cx=\"203.8\" cy=\"112\" r=\"5\" class=\"d2\"><title>6</title></circle><circle cx=\"141.9\" cy=\"112\" r=\"5\" class=\"d2\"><title>3</title></circle><circle cx=\"183.1\" cy=\"90\" r=\"5\" class=\"d2\"><title>5</title></circle><circle cx=\"121.2\" cy=\"112\" r=\"5\" class=\"d2\"><title>2</title></circle><circle cx=\"141.9\" cy=\"101\" r=\"5\" class=\"d2\"><title>3</title></circle><text x=\"72\" y=\"116\" class=\"tb\" text-anchor=\"end\">Group 2</text><line x1=\"183.1\" y1=\"14\" x2=\"183.1\" y2=\"124\" class=\"guide\"/><text x=\"183.1\" y=\"10\" class=\"ts\" text-anchor=\"middle\">mean = median = mode = 5</text><text x=\"410\" y=\"46\" class=\"tb\" text-anchor=\"end\">S = 2.345</text><text x=\"410\" y=\"92\" class=\"tb\" text-anchor=\"end\">S = 4.093</text></svg>",
